() => {
    if (!mapRef.current || markers.length === 0) return;

    // Clean up previous instance
    if (mapInstanceRef.current) {
      mapInstanceRef.current.remove();
      mapInstanceRef.current = null;
    }

    const map = L.map(mapRef.current, {
      zoomControl: true,
      attributionControl: true,
      scrollWheelZoom: true,
    });

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      maxZoom: 19,
      attribution:
        '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
    }).addTo(map);

    const bounds = L.latLngBounds([]);

    for (const marker of markers) {
      const color = TIME_COLORS[marker.timeOfDay] || "#F25D3B";
      const iconElement = document.createElement("div");
      Object.assign(iconElement.style, {
        width: "28px",
        height: "28px",
        background: color,
        border: "3px solid white",
        borderRadius: "50%",
        boxShadow: "0 2px 6px rgba(0,0,0,0.3)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: "white",
        fontSize: "11px",
        fontWeight: "700",
      });
      iconElement.textContent = String(marker.dayNumber);
      const icon = L.divIcon({
        className: "",
        html: iconElement,
        iconSize: [28, 28],
        iconAnchor: [14, 14],
      });
      const label = document.createElement("div");
      const dayLabel = document.createElement("strong");
      dayLabel.textContent = `Day ${marker.dayNumber}`;
      label.append(
        dayLabel,
        document.createTextNode(` · ${marker.timeOfDay}`),
        document.createElement("br"),
        document.createTextNode(marker.name),
      );
      L.marker([marker.lat, marker.lng], { icon }).addTo(map).bindPopup(label);

      bounds.extend([marker.lat, marker.lng]);
    }

    map.fitBounds(bounds, { padding: [40, 40], maxZoom: 14 });

    mapInstanceRef.current = map;

    const resizeFrame = requestAnimationFrame(() => {
      map.invalidateSize();
    });

    return () => {
      cancelAnimationFrame(resizeFrame);
      map.remove();
      mapInstanceRef.current = null;
    };
  }

